link.script:
tailwind.config = {
    darkMode: 'class',
    theme: {
        extend: {
            fontFamily: {
                sans: ['Inter', '-apple-system', 'BlinkMacSystemFont', 'sans-serif'],
                mono: ['JetBrains Mono', 'monospace'],
            }
        }
    }
}

body.script:
(function () {
    /* =====================================================================
       1. LIGHT / DARK THEME TOGGLE (Default: Light Pearl #f8fafc)
       ===================================================================== */
    const htmlEl = document.documentElement;
    const themeBtn = document.getElementById('theme-toggle');
    const savedTheme = localStorage.getItem('buraktonoz_theme');

    if (savedTheme === 'dark') {
        htmlEl.classList.add('dark');
        htmlEl.classList.remove('light');
    }

    themeBtn.addEventListener('click', () => {
        const isDark = htmlEl.classList.toggle('dark');
        htmlEl.classList.toggle('light', !isDark);
        localStorage.setItem('buraktonoz_theme', isDark ? 'dark' : 'light');
    });

    /* =====================================================================
       2. INTERACTIVE RGB AURORA SMOKE CANVAS
       ===================================================================== */
    const canvas = document.getElementById('aurora-smoke-canvas');
    const ctx = canvas.getContext('2d');
    let width = window.innerWidth;
    let height = window.innerHeight;

    function resizeCanvas() {
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = width;
        canvas.height = height;
    }
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    const smokeOrbs = [
        { x: 0.18, y: 0.20, vx: 0.00025, vy: 0.00018, r: 0.44, light: 'rgba(56, 189, 248, 0.20)', dark: 'rgba(14, 165, 233, 0.14)' },  // Sky Cyan
        { x: 0.82, y: 0.22, vx: -0.00022, vy: 0.00026, r: 0.46, light: 'rgba(139, 92, 246, 0.16)', dark: 'rgba(139, 92, 246, 0.12)' }, // Violet
        { x: 0.48, y: 0.78, vx: 0.00019, vy: -0.00022, r: 0.48, light: 'rgba(16, 185, 129, 0.16)', dark: 'rgba(16, 185, 129, 0.10)' }, // Emerald
        { x: 0.85, y: 0.80, vx: -0.00024, vy: -0.00019, r: 0.40, light: 'rgba(244, 63, 94, 0.14)', dark: 'rgba(244, 63, 94, 0.09)' }   // Rose
    ];

    let pointer = { x: 0.5, y: 0.5, tx: 0.5, ty: 0.5 };
    window.addEventListener('pointermove', (e) => {
        pointer.tx = e.clientX / Math.max(width, 1);
        pointer.ty = e.clientY / Math.max(height, 1);
    });

    function renderAuroraSmoke() {
        ctx.clearRect(0, 0, width, height);
        const isDark = htmlEl.classList.contains('dark');
        const maxDim = Math.max(width, height);

        pointer.x += (pointer.tx - pointer.x) * 0.04;
        pointer.y += (pointer.ty - pointer.y) * 0.04;

        smokeOrbs.forEach((orb, idx) => {
            orb.x += orb.vx;
            orb.y += orb.vy;
            if (orb.x < 0.05 || orb.x > 0.95) orb.vx *= -1;
            if (orb.y < 0.05 || orb.y > 0.95) orb.vy *= -1;

            const cx = (orb.x + (pointer.x - 0.5) * 0.05 * (idx % 2 === 0 ? 1 : -1)) * width;
            const cy = (orb.y + (pointer.y - 0.5) * 0.05 * (idx % 2 === 0 ? -1 : 1)) * height;
            const radius = orb.r * maxDim;

            const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
            grad.addColorStop(0, isDark ? orb.dark : orb.light);
            grad.addColorStop(1, 'rgba(0, 0, 0, 0)');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(cx, cy, radius, 0, Math.PI * 2);
            ctx.fill();
        });

        requestAnimationFrame(renderAuroraSmoke);
    }

    window.onload = function () {
        renderAuroraSmoke();
    };

    /* =====================================================================
       3. LINEAR / STRIPE STYLE SPOTLIGHT RADIAL GLOW ON CARDS
       ===================================================================== */
    const spotlightCards = document.querySelectorAll('.spotlight-card');
    spotlightCards.forEach((card) => {
        card.addEventListener('pointermove', (e) => {
            const rect = card.getBoundingClientRect();
            card.style.setProperty('--mouse-x', `${e.clientX - rect.left}px`);
            card.style.setProperty('--mouse-y', `${e.clientY - rect.top}px`);
        });
    });

    /* =====================================================================
       4. LIVE PROJECT FILTER & INSTANT SEARCH
       ===================================================================== */
    const searchInput = document.getElementById('project-search');
    const filterBtns = document.querySelectorAll('.filter-btn');
    const projectCards = document.querySelectorAll('.project-card');
    const visibleCountBadge = document.getElementById('visible-count-badge');
    const emptyState = document.getElementById('empty-state');
    const resetSearchBtn = document.getElementById('reset-search-btn');
    let activeCategory = 'all';

    function applyFilter() {
        const query = (searchInput.value || '').toLocaleLowerCase('tr-TR').trim();
        let count = 0;

        projectCards.forEach((card) => {
            const category = card.getAttribute('data-category');
            const content = card.innerText.toLocaleLowerCase('tr-TR');
            const matchesCategory = (activeCategory === 'all' || category === activeCategory);
            const matchesQuery = (!query || content.includes(query));

            if (matchesCategory && matchesQuery) {
                card.classList.remove('hidden');
                count++;
            } else {
                card.classList.add('hidden');
            }
        });

        visibleCountBadge.textContent = `${count} Proje`;
        emptyState.classList.toggle('hidden', count > 0);
    }

    filterBtns.forEach((btn) => {
        btn.addEventListener('click', () => {
            activeCategory = btn.getAttribute('data-filter');
            filterBtns.forEach((b) => {
                b.className = 'filter-btn px-3.5 py-1.5 rounded-xl text-xs font-medium bg-white/75 dark:bg-zinc-800/70 text-slate-600 dark:text-zinc-300 hover:bg-white dark:hover:bg-zinc-800 border border-slate-200/70 dark:border-zinc-700/70 transition';
            });
            btn.className = 'filter-btn active px-3.5 py-1.5 rounded-xl text-xs font-semibold bg-slate-900 text-white dark:bg-white dark:text-zinc-900 shadow-sm transition';
            applyFilter();
        });
    });

    searchInput.addEventListener('input', applyFilter);

    resetSearchBtn.addEventListener('click', () => {
        searchInput.value = '';
        activeCategory = 'all';
        filterBtns[0].click();
    });

    /* =====================================================================
       5. 1-CLICK EMAIL COPY WITH TOAST NOTIFICATION
       ===================================================================== */
    const toastEl = document.getElementById('toast-notification');
    const toastText = document.getElementById('toast-text');
    let toastTimer = null;

    function showToast(msg) {
        toastText.textContent = msg;
        toastEl.classList.remove('opacity-0', 'translate-y-3');
        toastEl.classList.add('opacity-100', 'translate-y-0');
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => {
            toastEl.classList.add('opacity-0', 'translate-y-3');
            toastEl.classList.remove('opacity-100', 'translate-y-0');
        }, 2600);
    }

    document.querySelectorAll('[data-copy-email]').forEach((btn) => {
        btn.addEventListener('click', () => {
            const email = btn.getAttribute('data-copy-email');
            const temp = document.createElement('textarea');
            temp.value = email;
            document.body.appendChild(temp);
            temp.select();
            document.execCommand('copy');
            document.body.removeChild(temp);
            showToast(`${email} panoya kopyalandı!`);
        });
    });

    /* =====================================================================
       6. DIRECT CONTACT FORM (FORMSUBMIT AJAX + MAILTO FALLBACK)
       ===================================================================== */
    const contactForm = document.getElementById('contact-form');
    const formStatus = document.getElementById('form-status');
    const submitBtn = document.getElementById('submit-btn');
    const submitBtnText = document.getElementById('submit-btn-text');

    contactForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const name = document.getElementById('sender-name').value.trim();
        const email = document.getElementById('sender-email').value.trim();
        const subject = document.getElementById('sender-subject').value.trim();
        const message = document.getElementById('sender-message').value.trim();

        submitBtn.disabled = true;
        submitBtnText.textContent = 'Gönderiliyor...';

        try {
            const response = await fetch('https://formsubmit.co/ajax/buraktonoz@gmail.com', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json'
                },
                body: JSON.stringify({
                    name: name,
                    email: email,
                    _subject: `[buraktonoz.com] ${subject} — ${name}`,
                    category: subject,
                    message: message
                })
            });

            if (response.ok) {
                formStatus.textContent = 'Mesajınız başarıyla buraktonoz@gmail.com adresine iletildi! Teşekkürler.';
                formStatus.className = 'text-xs font-semibold text-emerald-600 dark:text-emerald-400';
                contactForm.reset();
                showToast('Mesajınız başarıyla gönderildi!');
            } else {
                throw new Error('Fallback to mailto');
            }
        } catch (err) {
            const mailSubject = encodeURIComponent(`[buraktonoz.com] ${subject} — ${name}`);
            const mailBody = encodeURIComponent(
                `Gönderen: ${name}\nE-Posta: ${email}\nKonu: ${subject}\n\nMesaj:\n${message}`
            );
            window.location.href = `mailto:buraktonoz@gmail.com?subject=${mailSubject}&body=${mailBody}`;
            formStatus.textContent = 'E-posta istemciniz açılıyor (buraktonoz@gmail.com)...';
            formStatus.className = 'text-xs font-semibold text-blue-600 dark:text-blue-400';
        } finally {
            submitBtn.disabled = false;
            submitBtnText.textContent = 'Mesajı Gönder';
        }
    });
})();
